    "path": "runtime/proxy/admission.js",
    "content": "import { normalizeHostname } from \"./contracts/network-policy.js\";\nfunction atStage(record, stage) {\n    return { ...record, stage };\n}\nexport class AdmissionRegistry {\n    #bindings = new Map();\n    #nextSerial = 1;\n    mint(host, policyGeneration, identity = {}) {\n        return Object.freeze({\n            v: 1,\n            host: normalizeHostname(host),\n            port: 443,\n            policyGeneration,\n            admittedAtMs: Date.now(),\n            connectionSerial: this.#nextSerial++,\n            stage: \"connect\",\n            ...identity,\n        });\n    }\n    bind(port, record) {\n        if (!Number.isInteger(port) || port < 1 || port > 65_535) {\n            throw new Error(`invalid admission connection port: ${port}`);\n        }\n        this.#bindings.set(port, { record });\n    }\n    observeTls(port, sniHostname) {\n        if (port === undefined)\n            return { kind: \"missing\" };\n        const binding = this.#bindings.get(port);\n        if (!binding)\n            return { kind: \"missing\" };\n        const { record } = binding;\n        if (sniHostname !== undefined) {\n            let observedHost;\n            try {\n                observedHost = normalizeHostname(sniHostname);\n            }\n            catch {\n                return { kind: \"host-mismatch\", record, observedHost: \"<unparseable>\" };\n            }\n            if (observedHost !== record.host) {\n                return { kind: \"host-mismatch\", record, observedHost };\n            }\n        }\n        binding.observedSerial = record.connectionSerial;\n        return { kind: \"admitted\", record: atStage(record, \"sni\") };\n    }\n    resolveRequest(port, observedSerial) {\n        if (port === undefined || observedSerial === undefined)\n            return undefined;\n        const binding = this.#bindings.get(port);\n        if (!binding\n            || binding.observedSerial !== binding.record.connectionSerial\n            || observedSerial !== binding.record.connectionSerial)\n            return undefined;\n        return atStage(binding.record, \"request\");\n    }\n    release(port, connectionSerial) {\n        const binding = this.#bindings.get(port);\n        if (binding?.record.connectionSerial === connectionSerial) {\n            this.#bindings.delete(port);\n        }\n    }\n    revokeSession(sessionKey) {\n        let revoked = 0;\n        for (const [port, binding] of this.#bindings) {\n            if (binding.record.sessionBinding?.sessionKey !== sessionKey)\n                continue;\n            this.#bindings.delete(port);\n            revoked += 1;\n        }\n        return revoked;\n    }\n    size() {\n        return this.#bindings.size;\n    }\n}\n"
